import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { isSourceRecord, readPage, repoRoot, wikiMarkdownFiles } from './wiki-graph.mjs';

// Generated by a producer that does not emit frontmatter yet; the library README is routed by hand in wiki/README.md Layer 3.
export const PRODUCER_OWNED = new Set(['wiki/image-library/README.md', 'wiki/soundtrack-library/README.md', 'wiki/comics-library/README.md']);

export function isMaintainedPage(relative) {
  return relative.startsWith('wiki/') && relative.endsWith('.md') && !isSourceRecord(relative) && !PRODUCER_OWNED.has(relative);
}

export function gate(root = repoRoot) {
  const findings = [];
  const pages = wikiMarkdownFiles(root).filter(isMaintainedPage);
  for (const relative of pages) {
    const bytes = fs.readFileSync(path.join(root, relative));
    try {
      const page = readPage(bytes, relative, { strict: true });
      if (!page) findings.push({ path: relative, finding: 'NO-FRONTMATTER' });
      else if (bytes[0] === 0xef) findings.push({ path: relative, finding: 'BOM-BEFORE-FENCE' });
    } catch (error) { findings.push({ path: relative, finding: error.message.replace(`${relative}: `, '')}); }
  }
  return { checked: pages.length, findings };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const result = gate();
  for (const finding of result.findings) process.stdout.write(`${finding.path}: ${finding.finding}\n`);
  process.stdout.write(`${JSON.stringify({ checked: result.checked, findings: result.findings.length })}\n`);
  process.exitCode = result.checked === 0 ? 3 : result.findings.length ? 2 : 0;
}
